/**
 * Dedicated IP Provisioning Module
 *
 * Creates and destroys per-tenant NAT Gateway + EIP + Subnet + Lambda
 * within the shared VPC for tenants requiring a unique outbound IP.
 *
 * Architecture: Single-VPC-Multi-NAT approach (shared VPC, per-tenant subnets)
 *
 * Provisioning creates:
 *   1. Elastic IP
 *   2. Public subnet (for NAT Gateway)
 *   3. Private subnet (for Lambda)
 *   4. Internet Gateway route in public subnet
 *   5. NAT Gateway in public subnet with EIP
 *   6. Route table for private subnet → NAT Gateway
 *   7. Security Group (outbound LDAP/LDAPS)
 *   8. IAM Role for per-tenant Lambda
 *   9. Lambda Function (code from S3, VPC-attached to private subnet)
 *
 * Cleanup reverses all of the above.
 */

import {
  EC2Client,
  AllocateAddressCommand,
  ReleaseAddressCommand,
  CreateSubnetCommand,
  DeleteSubnetCommand,
  CreateNatGatewayCommand,
  DeleteNatGatewayCommand,
  DescribeNatGatewaysCommand,
  CreateRouteTableCommand,
  DeleteRouteTableCommand,
  CreateRouteCommand,
  AssociateRouteTableCommand,
  DisassociateRouteTableCommand,
  CreateSecurityGroupCommand,
  DeleteSecurityGroupCommand,
  AuthorizeSecurityGroupEgressCommand,
  RevokeSecurityGroupEgressCommand,
  CreateTagsCommand,
  DescribeSubnetsCommand,
  DescribeRouteTablesCommand,
} from '@aws-sdk/client-ec2';
import {
  LambdaClient,
  CreateFunctionCommand,
  DeleteFunctionCommand,
  GetFunctionCommand,
  waitUntilFunctionActiveV2,
} from '@aws-sdk/client-lambda';
import {
  IAMClient,
  CreateRoleCommand,
  DeleteRoleCommand,
  AttachRolePolicyCommand,
  DetachRolePolicyCommand,
  PutRolePolicyCommand,
  DeleteRolePolicyCommand,
} from '@aws-sdk/client-iam';
import { DynamoDBClient, GetItemCommand, UpdateItemCommand } from '@aws-sdk/client-dynamodb';

const ec2 = new EC2Client({});
const lambdaClient = new LambdaClient({});
const iam = new IAMClient({});
const dynamodb = new DynamoDBClient({});

const ACCOUNT_ID = process.env.ACCOUNT_ID || '';
const AWS_REGION = process.env.AWS_REGION || 'us-east-1';
const CONFIG_TABLE = process.env.CONFIG_TABLE || 'amfa-configtable';
const TENANT_TABLE = process.env.AMFATENANT_TABLE || 'amfa-tenanttable';
const VPC_ID = process.env.VPC_ID || '';
const IGW_ID = process.env.IGW_ID || ''; // Internet Gateway of shared VPC
const WORKER_CODE_S3_BUCKET = process.env.WORKER_CODE_S3_BUCKET || `${ACCOUNT_ID}-${AWS_REGION}-ad-sync-state`;
const WORKER_CODE_S3_KEY = process.env.WORKER_CODE_S3_KEY || 'worker-code/latest.zip';
const SYNC_STATE_BUCKET = process.env.SYNC_STATE_BUCKET || `${ACCOUNT_ID}-${AWS_REGION}-ad-sync-state`;
const NAT_EIP_ADDRESS = process.env.NAT_EIP_ADDRESS || ''; // shared NAT IP (fallback)

// CIDR base for dedicated subnets: 10.0.{index}.0/26 (private) + 10.0.{index}.64/26 (public)
const CIDR_BASE = '10.0';
const CIDR_START_INDEX = 10; // Indices 0-9 reserved for shared infra

/**
 * Enable dedicated IP for a tenant.
 *
 * Creates all required AWS resources and updates the tenant's adSyncConfig.
 *
 * @param {string} tenantId
 * @returns {Promise<Object>} { dedicatedEipAddress, dedicatedLambdaArn, ... }
 */
export async function enableDedicatedIp(tenantId) {
  console.log(JSON.stringify({ level: "INFO", event: "DEDICATED_IP_ENABLE_START", tenantId }));

  if (!VPC_ID) {
    throw new Error('VPC_ID not configured. Shared VPC must be deployed first.');
  }
  if (!IGW_ID) {
    throw new Error('IGW_ID not configured. Internet Gateway must exist in shared VPC.');
  }

  // Track created resources for rollback
  const resources = {};

  try {
    // Step 1: Allocate CIDR index
    const cidrIndex = await allocateCidrIndex(tenantId);
    resources.cidrIndex = cidrIndex;
    const privateCidr = `${CIDR_BASE}.${cidrIndex}.0/26`;
    const publicCidr = `${CIDR_BASE}.${cidrIndex}.64/26`;

    console.log(JSON.stringify({ level: "INFO", event: "CIDR_ALLOCATED", tenantId, cidrIndex, privateCidr, publicCidr }));

    // Step 2: Allocate Elastic IP
    const eipResult = await ec2.send(new AllocateAddressCommand({ Domain: 'vpc' }));
    resources.eipAllocationId = eipResult.AllocationId;
    resources.eipAddress = eipResult.PublicIp;
    await tagResource(eipResult.AllocationId, tenantId, 'EIP');
    console.log(JSON.stringify({ level: "INFO", event: "EIP_ALLOCATED", tenantId, eip: eipResult.PublicIp }));

    // Step 3: Create public subnet (for NAT Gateway)
    const publicSubnet = await ec2.send(new CreateSubnetCommand({
      VpcId: VPC_ID,
      CidrBlock: publicCidr,
      AvailabilityZone: `${AWS_REGION}a`,
      TagSpecifications: [{
        ResourceType: 'subnet',
        Tags: [
          { Key: 'Name', Value: `dedicated-ip-public-${tenantId}` },
          { Key: 'TenantId', Value: tenantId },
          { Key: 'Purpose', Value: 'dedicated-ip-nat' },
        ],
      }],
    }));
    resources.publicSubnetId = publicSubnet.Subnet.SubnetId;
    console.log(JSON.stringify({ level: "INFO", event: "PUBLIC_SUBNET_CREATED", tenantId, subnetId: resources.publicSubnetId }));

    // Step 4: Create private subnet (for Lambda)
    const privateSubnet = await ec2.send(new CreateSubnetCommand({
      VpcId: VPC_ID,
      CidrBlock: privateCidr,
      AvailabilityZone: `${AWS_REGION}a`,
      TagSpecifications: [{
        ResourceType: 'subnet',
        Tags: [
          { Key: 'Name', Value: `dedicated-ip-private-${tenantId}` },
          { Key: 'TenantId', Value: tenantId },
          { Key: 'Purpose', Value: 'dedicated-ip-lambda' },
        ],
      }],
    }));
    resources.privateSubnetId = privateSubnet.Subnet.SubnetId;
    console.log(JSON.stringify({ level: "INFO", event: "PRIVATE_SUBNET_CREATED", tenantId, subnetId: resources.privateSubnetId }));

    // Step 5: Create route table for public subnet → IGW
    const publicRt = await ec2.send(new CreateRouteTableCommand({ VpcId: VPC_ID }));
    resources.publicRouteTableId = publicRt.RouteTable.RouteTableId;
    await tagResource(resources.publicRouteTableId, tenantId, 'PublicRT');

    await ec2.send(new CreateRouteCommand({
      RouteTableId: resources.publicRouteTableId,
      DestinationCidrBlock: '0.0.0.0/0',
      GatewayId: IGW_ID,
    }));

    const publicAssoc = await ec2.send(new AssociateRouteTableCommand({
      RouteTableId: resources.publicRouteTableId,
      SubnetId: resources.publicSubnetId,
    }));
    resources.publicRtAssociationId = publicAssoc.AssociationId;
    console.log(JSON.stringify({ level: "INFO", event: "PUBLIC_ROUTE_TABLE_CREATED", tenantId }));

    // Step 6: Create NAT Gateway in public subnet with EIP
    const natGw = await ec2.send(new CreateNatGatewayCommand({
      SubnetId: resources.publicSubnetId,
      AllocationId: resources.eipAllocationId,
      TagSpecifications: [{
        ResourceType: 'natgateway',
        Tags: [
          { Key: 'Name', Value: `dedicated-ip-nat-${tenantId}` },
          { Key: 'TenantId', Value: tenantId },
        ],
      }],
    }));
    resources.natGatewayId = natGw.NatGateway.NatGatewayId;
    console.log(JSON.stringify({ level: "INFO", event: "NAT_GATEWAY_CREATING", tenantId, natGwId: resources.natGatewayId }));

    // Wait for NAT Gateway to become available (can take 1-2 minutes)
    await waitForNatGateway(resources.natGatewayId);
    console.log(JSON.stringify({ level: "INFO", event: "NAT_GATEWAY_AVAILABLE", tenantId }));

    // Step 7: Create route table for private subnet → NAT Gateway
    const privateRt = await ec2.send(new CreateRouteTableCommand({ VpcId: VPC_ID }));
    resources.privateRouteTableId = privateRt.RouteTable.RouteTableId;
    await tagResource(resources.privateRouteTableId, tenantId, 'PrivateRT');

    await ec2.send(new CreateRouteCommand({
      RouteTableId: resources.privateRouteTableId,
      DestinationCidrBlock: '0.0.0.0/0',
      NatGatewayId: resources.natGatewayId,
    }));

    const privateAssoc = await ec2.send(new AssociateRouteTableCommand({
      RouteTableId: resources.privateRouteTableId,
      SubnetId: resources.privateSubnetId,
    }));
    resources.privateRtAssociationId = privateAssoc.AssociationId;
    console.log(JSON.stringify({ level: "INFO", event: "PRIVATE_ROUTE_TABLE_CREATED", tenantId }));

    // Step 8: Create Security Group (outbound LDAP/LDAPS only)
    const sg = await ec2.send(new CreateSecurityGroupCommand({
      GroupName: `dedicated-ip-sg-${tenantId}`,
      Description: `Security group for dedicated IP Lambda - tenant ${tenantId}`,
      VpcId: VPC_ID,
    }));
    resources.securityGroupId = sg.GroupId;
    await tagResource(resources.securityGroupId, tenantId, 'SG');

    // Revoke default all-outbound rule, then add specific LDAP/LDAPS/DNS rules
    try {
      await ec2.send(new RevokeSecurityGroupEgressCommand({
        GroupId: resources.securityGroupId,
        IpPermissions: [{ IpProtocol: '-1', IpRanges: [{ CidrIp: '0.0.0.0/0' }] }],
      }));
    } catch (e) { /* ignore if already revoked */ }

    // Allow outbound: LDAP (389), LDAPS (636), DNS (53), HTTPS (443)
    await ec2.send(new AuthorizeSecurityGroupEgressCommand({
      GroupId: resources.securityGroupId,
      IpPermissions: [
        { IpProtocol: 'tcp', FromPort: 389, ToPort: 389, IpRanges: [{ CidrIp: '0.0.0.0/0' }] },
        { IpProtocol: 'tcp', FromPort: 636, ToPort: 636, IpRanges: [{ CidrIp: '0.0.0.0/0' }] },
        { IpProtocol: 'tcp', FromPort: 53, ToPort: 53, IpRanges: [{ CidrIp: '0.0.0.0/0' }] },
        { IpProtocol: 'udp', FromPort: 53, ToPort: 53, IpRanges: [{ CidrIp: '0.0.0.0/0' }] },
        { IpProtocol: 'tcp', FromPort: 443, ToPort: 443, IpRanges: [{ CidrIp: '0.0.0.0/0' }] },
      ],
    }));
    console.log(JSON.stringify({ level: "INFO", event: "SECURITY_GROUP_CREATED", tenantId }));

    // Step 9: Create IAM Role
    const roleName = `ad-sync-dedicated-${tenantId}`;
    resources.iamRoleName = roleName;
    const roleArn = await createWorkerRole(roleName, tenantId);
    resources.iamRoleArn = roleArn;

    // Wait for IAM role propagation
    await new Promise(r => setTimeout(r, 10000));
    console.log(JSON.stringify({ level: "INFO", event: "IAM_ROLE_CREATED", tenantId, roleName }));

    // Step 10: Create Lambda Function
    const functionName = `ad-sync-worker-tenant-${tenantId}`;
    resources.lambdaFunctionName = functionName;

    await lambdaClient.send(new CreateFunctionCommand({
      FunctionName: functionName,
      Runtime: 'nodejs22.x',
      Handler: 'index.handler',
      Role: roleArn,
      Code: {
        S3Bucket: WORKER_CODE_S3_BUCKET,
        S3Key: WORKER_CODE_S3_KEY,
      },
      VpcConfig: {
        SubnetIds: [resources.privateSubnetId],
        SecurityGroupIds: [resources.securityGroupId],
      },
      Environment: {
        Variables: {
          CONFIG_TABLE: CONFIG_TABLE,
          TENANT_TABLE: TENANT_TABLE,
          SYNC_STATE_BUCKET: SYNC_STATE_BUCKET,
        },
      },
      Timeout: 900, // 15 minutes
      MemorySize: 1024,
      Tags: {
        TenantId: tenantId,
        Purpose: 'dedicated-ip-ad-sync-worker',
      },
    }));

    // Wait for Lambda to be active
    await waitUntilFunctionActiveV2(
      { client: lambdaClient, maxWaitTime: 120 },
      { FunctionName: functionName },
    );

    const lambdaArn = `arn:aws:lambda:${AWS_REGION}:${ACCOUNT_ID}:function:${functionName}`;
    resources.lambdaArn = lambdaArn;
    console.log(JSON.stringify({ level: "INFO", event: "LAMBDA_CREATED", tenantId, functionName }));

    // Step 11: Update adSyncConfig with dedicated IP info
    await updateAdSyncConfigDedicatedIp(tenantId, {
      mode: 'dedicated',
      dedicatedLambdaArn: lambdaArn,
      dedicatedEipAddress: resources.eipAddress,
      dedicatedResources: resources,
    });

    console.log(JSON.stringify({ level: "INFO", event: "DEDICATED_IP_ENABLE_COMPLETE", tenantId, eip: resources.eipAddress }));

    return {
      dedicatedEipAddress: resources.eipAddress,
      dedicatedLambdaArn: lambdaArn,
      networkConfig: { mode: 'dedicated', ...resources },
    };
  } catch (error) {
    console.error(JSON.stringify({ level: "ERROR", event: "DEDICATED_IP_ENABLE_FAILED", tenantId, error: error.message, resources }));

    // Rollback created resources
    await rollbackResources(tenantId, resources);
    throw error;
  }
}

/**
 * Disable dedicated IP for a tenant — cleanup all provisioned resources.
 */
export async function disableDedicatedIp(tenantId) {
  console.log(JSON.stringify({ level: "INFO", event: "DEDICATED_IP_DISABLE_START", tenantId }));

  // Load current config to get resource IDs
  const adSyncConfig = await loadAdSyncConfig(tenantId);
  const resources = adSyncConfig?.networkConfig?.dedicatedResources;

  if (!resources) {
    console.log(JSON.stringify({ level: "WARN", event: "NO_DEDICATED_RESOURCES", tenantId }));
    return { message: 'No dedicated IP resources found to clean up' };
  }

  await rollbackResources(tenantId, resources);

  // Deallocate CIDR index
  if (resources.cidrIndex) {
    await deallocateCidrIndex(resources.cidrIndex, tenantId);
  }

  // Update config back to shared mode
  await updateAdSyncConfigDedicatedIp(tenantId, { mode: 'shared' });

  console.log(JSON.stringify({ level: "INFO", event: "DEDICATED_IP_DISABLE_COMPLETE", tenantId }));
  return { message: 'Dedicated IP resources cleaned up successfully' };
}

/**
 * Get provisioning status for a tenant.
 */
export async function getDedicatedIpStatus(tenantId) {
  const adSyncConfig = await loadAdSyncConfig(tenantId);
  const networkConfig = adSyncConfig?.networkConfig || {};

  return {
    mode: networkConfig.mode || 'shared',
    dedicatedEipAddress: networkConfig.dedicatedEipAddress || null,
    dedicatedLambdaArn: networkConfig.dedicatedLambdaArn || null,
    sharedNatEipAddress: NAT_EIP_ADDRESS,
  };
}

// ─── Helper Functions ────────────────────────────────────────────────────────

async function waitForNatGateway(natGatewayId, maxWaitSec = 180) {
  const startTime = Date.now();
  while (Date.now() - startTime < maxWaitSec * 1000) {
    const desc = await ec2.send(new DescribeNatGatewaysCommand({
      NatGatewayIds: [natGatewayId],
    }));
    const state = desc.NatGateways?.[0]?.State;
    if (state === 'available') return;
    if (state === 'failed') throw new Error(`NAT Gateway ${natGatewayId} failed to create`);
    await new Promise(r => setTimeout(r, 5000));
  }
  throw new Error(`NAT Gateway ${natGatewayId} did not become available within ${maxWaitSec}s`);
}

async function waitForNatGatewayDeleted(natGatewayId, maxWaitSec = 180) {
  const startTime = Date.now();
  while (Date.now() - startTime < maxWaitSec * 1000) {
    try {
      const desc = await ec2.send(new DescribeNatGatewaysCommand({
        NatGatewayIds: [natGatewayId],
      }));
      const state = desc.NatGateways?.[0]?.State;
      if (state === 'deleted') return;
    } catch (e) {
      return; // Not found = deleted
    }
    await new Promise(r => setTimeout(r, 5000));
  }
}

async function tagResource(resourceId, tenantId, resourceType) {
  await ec2.send(new CreateTagsCommand({
    Resources: [resourceId],
    Tags: [
      { Key: 'Name', Value: `dedicated-ip-${resourceType.toLowerCase()}-${tenantId}` },
      { Key: 'TenantId', Value: tenantId },
      { Key: 'ManagedBy', Value: 'vpnconfig-lambda' },
    ],
  }));
}

async function createWorkerRole(roleName, tenantId) {
  const assumeRolePolicy = JSON.stringify({
    Version: '2012-10-17',
    Statement: [{
      Effect: 'Allow',
      Principal: { Service: 'lambda.amazonaws.com' },
      Action: 'sts:AssumeRole',
    }],
  });

  const result = await iam.send(new CreateRoleCommand({
    RoleName: roleName,
    AssumeRolePolicyDocument: assumeRolePolicy,
    Tags: [
      { Key: 'TenantId', Value: tenantId },
      { Key: 'Purpose', Value: 'dedicated-ip-ad-sync-worker' },
    ],
  }));

  // Attach managed policies
  await iam.send(new AttachRolePolicyCommand({
    RoleName: roleName,
    PolicyArn: 'arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole',
  }));

  // Inline policy for DynamoDB, Secrets Manager, S3, Cognito
  const inlinePolicy = JSON.stringify({
    Version: '2012-10-17',
    Statement: [
      {
        Effect: 'Allow',
        Action: ['dynamodb:GetItem', 'dynamodb:Query', 'dynamodb:UpdateItem', 'dynamodb:PutItem'],
        Resource: [
          `arn:aws:dynamodb:${AWS_REGION}:${ACCOUNT_ID}:table/${CONFIG_TABLE}`,
          `arn:aws:dynamodb:${AWS_REGION}:${ACCOUNT_ID}:table/${TENANT_TABLE}`,
          `arn:aws:dynamodb:${AWS_REGION}:${ACCOUNT_ID}:table/${TENANT_TABLE}/index/*`,
        ],
      },
      {
        Effect: 'Allow',
        Action: ['secretsmanager:GetSecretValue'],
        Resource: [`arn:aws:secretsmanager:${AWS_REGION}:${ACCOUNT_ID}:secret:apersona/*`],
      },
      {
        Effect: 'Allow',
        Action: ['s3:GetObject', 's3:PutObject', 's3:ListBucket'],
        Resource: [
          `arn:aws:s3:::${SYNC_STATE_BUCKET}`,
          `arn:aws:s3:::${SYNC_STATE_BUCKET}/*`,
        ],
      },
      {
        Effect: 'Allow',
        Action: [
          'cognito-idp:ListUsers',
          'cognito-idp:AdminCreateUser',
          'cognito-idp:AdminUpdateUserAttributes',
          'cognito-idp:AdminAddUserToGroup',
          'cognito-idp:AdminRemoveUserFromGroup',
          'cognito-idp:AdminListGroupsForUser',
          'cognito-idp:AdminDeleteUser',
          'cognito-idp:AdminGetUser',
          'cognito-idp:AdminDisableUser',
          'cognito-idp:AdminEnableUser',
          'cognito-idp:ListUsersInGroup',
        ],
        Resource: [`arn:aws:cognito-idp:${AWS_REGION}:${ACCOUNT_ID}:userpool/*`],
      },
    ],
  });

  await iam.send(new PutRolePolicyCommand({
    RoleName: roleName,
    PolicyName: 'ad-sync-worker-permissions',
    PolicyDocument: inlinePolicy,
  }));

  return result.Role.Arn;
}

async function deleteWorkerRole(roleName) {
  try {
    // Detach managed policies
    await iam.send(new DetachRolePolicyCommand({
      RoleName: roleName,
      PolicyArn: 'arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole',
    })).catch(() => {});

    // Delete inline policy
    await iam.send(new DeleteRolePolicyCommand({
      RoleName: roleName,
      PolicyName: 'ad-sync-worker-permissions',
    })).catch(() => {});

    // Delete role
    await iam.send(new DeleteRoleCommand({ RoleName: roleName }));
    console.log(JSON.stringify({ level: "INFO", event: "IAM_ROLE_DELETED", roleName }));
  } catch (e) {
    console.warn(JSON.stringify({ level: "WARN", event: "IAM_ROLE_DELETE_FAILED", roleName, error: e.message }));
  }
}

/**
 * Rollback/cleanup all created resources (in reverse order).
 */
async function rollbackResources(tenantId, resources) {
  console.log(JSON.stringify({ level: "INFO", event: "ROLLBACK_START", tenantId, resources: Object.keys(resources) }));

  // Delete Lambda
  if (resources.lambdaFunctionName) {
    try {
      await lambdaClient.send(new DeleteFunctionCommand({ FunctionName: resources.lambdaFunctionName }));
      console.log(JSON.stringify({ level: "INFO", event: "LAMBDA_DELETED", tenantId }));
    } catch (e) { console.warn(`[ROLLBACK] Lambda delete failed: ${e.message}`); }
  }

  // Delete IAM Role
  if (resources.iamRoleName) {
    await deleteWorkerRole(resources.iamRoleName);
  }

  // Delete NAT Gateway (must wait for deletion before releasing EIP)
  if (resources.natGatewayId) {
    try {
      await ec2.send(new DeleteNatGatewayCommand({ NatGatewayId: resources.natGatewayId }));
      await waitForNatGatewayDeleted(resources.natGatewayId);
      console.log(JSON.stringify({ level: "INFO", event: "NAT_GATEWAY_DELETED", tenantId }));
    } catch (e) { console.warn(`[ROLLBACK] NAT Gateway delete failed: ${e.message}`); }
  }

  // Disassociate and delete route tables
  if (resources.privateRtAssociationId) {
    try { await ec2.send(new DisassociateRouteTableCommand({ AssociationId: resources.privateRtAssociationId })); } catch (e) {}
  }
  if (resources.privateRouteTableId) {
    try { await ec2.send(new DeleteRouteTableCommand({ RouteTableId: resources.privateRouteTableId })); } catch (e) {}
  }
  if (resources.publicRtAssociationId) {
    try { await ec2.send(new DisassociateRouteTableCommand({ AssociationId: resources.publicRtAssociationId })); } catch (e) {}
  }
  if (resources.publicRouteTableId) {
    try { await ec2.send(new DeleteRouteTableCommand({ RouteTableId: resources.publicRouteTableId })); } catch (e) {}
  }

  // Delete Security Group
  if (resources.securityGroupId) {
    try {
      await ec2.send(new DeleteSecurityGroupCommand({ GroupId: resources.securityGroupId }));
      console.log(JSON.stringify({ level: "INFO", event: "SG_DELETED", tenantId }));
    } catch (e) { console.warn(`[ROLLBACK] SG delete failed: ${e.message}`); }
  }

  // Delete Subnets
  if (resources.privateSubnetId) {
    try { await ec2.send(new DeleteSubnetCommand({ SubnetId: resources.privateSubnetId })); } catch (e) {}
  }
  if (resources.publicSubnetId) {
    try { await ec2.send(new DeleteSubnetCommand({ SubnetId: resources.publicSubnetId })); } catch (e) {}
  }

  // Release EIP (must be after NAT Gateway is deleted)
  if (resources.eipAllocationId) {
    try {
      await ec2.send(new ReleaseAddressCommand({ AllocationId: resources.eipAllocationId }));
      console.log(JSON.stringify({ level: "INFO", event: "EIP_RELEASED", tenantId }));
    } catch (e) { console.warn(`[ROLLBACK] EIP release failed: ${e.message}`); }
  }

  console.log(JSON.stringify({ level: "INFO", event: "ROLLBACK_COMPLETE", tenantId }));
}

// ─── CIDR Allocation Tracker ─────────────────────────────────────────────────

async function allocateCidrIndex(tenantId, maxRetries = 5) {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    // Read current allocation from DynamoDB
    const item = await dynamodb.send(new GetItemCommand({
      TableName: TENANT_TABLE,
      Key: { id: { S: 'DEDICATED_IP#cidr-index' }, sk: { S: 'DEDICATED_IP#cidr-index' } },
    }));

    let nextIndex = CIDR_START_INDEX;
    let allocations = {};

    if (item.Item) {
      nextIndex = parseInt(item.Item.nextIndex?.N || String(CIDR_START_INDEX));
      allocations = JSON.parse(item.Item.allocations?.S || '{}');
    }

    // Check if tenant already has an allocation
    const existing = Object.entries(allocations).find(([, tid]) => tid === tenantId);
    if (existing) {
      return parseInt(existing[0]);
    }

    // Allocate next index with optimistic locking
    const allocatedIndex = nextIndex;
    allocations[String(allocatedIndex)] = tenantId;

    try {
      await dynamodb.send(new UpdateItemCommand({
        TableName: TENANT_TABLE,
        Key: { id: { S: 'DEDICATED_IP#cidr-index' }, sk: { S: 'DEDICATED_IP#cidr-index' } },
        UpdateExpression: 'SET nextIndex = :next, allocations = :alloc, #t = :type',
        // Optimistic lock: only succeed if nextIndex hasn't changed since we read it
        ConditionExpression: 'attribute_not_exists(nextIndex) OR nextIndex = :expected',
        ExpressionAttributeNames: { '#t': 'type' },
        ExpressionAttributeValues: {
          ':next': { N: String(allocatedIndex + 1) },
          ':alloc': { S: JSON.stringify(allocations) },
          ':type': { S: 'cidr-allocation' },
          ':expected': { N: String(nextIndex) },
        },
      }));

      return allocatedIndex;
    } catch (e) {
      if (e.name === 'ConditionalCheckFailedException') {
        // Another concurrent invocation allocated this index — retry
        console.log(JSON.stringify({ level: "WARN", event: "CIDR_ALLOC_CONFLICT", tenantId, attempt, nextIndex }));
        await new Promise(r => setTimeout(r, 100 * (attempt + 1))); // backoff
        continue;
      }
      throw e;
    }
  }

  throw new Error(`Failed to allocate CIDR index after ${maxRetries} retries (concurrent conflicts)`);
}

async function deallocateCidrIndex(index, tenantId) {
  try {
    const item = await dynamodb.send(new GetItemCommand({
      TableName: TENANT_TABLE,
      Key: { id: { S: 'DEDICATED_IP#cidr-index' }, sk: { S: 'DEDICATED_IP#cidr-index' } },
    }));

    if (item.Item) {
      const allocations = JSON.parse(item.Item.allocations?.S || '{}');
      delete allocations[String(index)];

      await dynamodb.send(new UpdateItemCommand({
        TableName: TENANT_TABLE,
        Key: { id: { S: 'DEDICATED_IP#cidr-index' }, sk: { S: 'DEDICATED_IP#cidr-index' } },
        UpdateExpression: 'SET allocations = :alloc',
        ExpressionAttributeValues: {
          ':alloc': { S: JSON.stringify(allocations) },
        },
      }));
    }
  } catch (e) {
    console.warn(JSON.stringify({ level: "WARN", event: "CIDR_DEALLOC_FAILED", index, tenantId, error: e.message }));
  }
}

// ─── Config Helpers ──────────────────────────────────────────────────────────

async function loadAdSyncConfig(tenantId) {
  const item = await dynamodb.send(new GetItemCommand({
    TableName: CONFIG_TABLE,
    Key: { id: { S: tenantId }, configtype: { S: 'adSyncConfig' } },
  }));
  return item.Item?.value?.S ? JSON.parse(item.Item.value.S) : null;
}

async function updateAdSyncConfigDedicatedIp(tenantId, networkConfig) {
  const existing = await loadAdSyncConfig(tenantId) || {};
  existing.networkConfig = networkConfig;

  await dynamodb.send(new UpdateItemCommand({
    TableName: CONFIG_TABLE,
    Key: { id: { S: tenantId }, configtype: { S: 'adSyncConfig' } },
    UpdateExpression: 'SET #val = :val',
    ExpressionAttributeNames: { '#val': 'value' },
    ExpressionAttributeValues: { ':val': { S: JSON.stringify(existing) } },
  }));
}
